    def var_breach_cluster_analysis(
        self, *, breaches: list[float] | list[list[float]]
    ) -> dict[str, Any]:
        """Analyse the clustering of VaR breaches.

        Reports the number of breach clusters (maximal runs of consecutive
        breaches), the longest run, and the mean run length — diagnostics for the
        independence assumption that the Christoffersen test formalises.

        Returns:
            The raw API response as a dict.
        """
        body = {"breaches": breaches}
        return self._client._request(
            "POST", "/api/v1/market-risk/var_breach_cluster_analysis", json_body=body
        )

    def var_by_risk_factor(
        self,
        *,
        factor_exposures: list[float] | list[list[float]],
        factor_cov: list[float] | list[list[float]],
        portfolio_value: float,
        confidence_level: float = 0.99,
        factor_names: list[str] | None = None,
    ) -> dict[str, Any]:
        """Decompose VaR across systematic risk factors (Euler allocation).

        Identical Euler decomposition to :func:`component_var` but expressed in
        risk-factor space: given portfolio factor exposures ``b`` and factor
        covariance ``F``, the factor contribution is
        ``z * b_i * (F b)_i / sigma_p`` and contributions sum to the total VaR.

        Returns:
            The raw API response as a dict.
        """
        body = {
            "factor_exposures": factor_exposures,
            "factor_cov": factor_cov,
            "portfolio_value": portfolio_value,
            "confidence_level": confidence_level,
            "factor_names": factor_names,
        }
        return self._client._request(
            "POST", "/api/v1/market-risk/var_by_risk_factor", json_body=body
        )

    def var_fan_chart(
        self,
        *,
        returns: list[float] | list[list[float]],
        portfolio_value: float,
        confidence_levels: list[float] = [0.9, 0.95, 0.99],
        horizon_days: int = 10,
    ) -> dict[str, Any]:
        """VaR fan chart — parametric VaR bands across confidence levels and horizons.

        Produces, for each confidence level, the VaR projected over 1..H days using
        square-root-of-time volatility scaling — the standard visualisation of how
        the loss envelope widens with the holding period.

        Returns:
            The raw API response as a dict.
        """
        body = {
            "returns": returns,
            "portfolio_value": portfolio_value,
            "confidence_levels": confidence_levels,
            "horizon_days": horizon_days,
        }
        return self._client._request("POST", "/api/v1/market-risk/var_fan_chart", json_body=body)

    def vega_pnl_attribution(self, *, vega: float, vol_move: float) -> dict[str, Any]:
        """Vega P&L component: ``ν · dσ``.

        Returns:
            The raw API response as a dict.
        """
        body = {"vega": vega, "vol_move": vol_move}
        return self._client._request(
            "POST", "/api/v1/market-risk/vega_pnl_attribution", json_body=body
        )

    def vega_surface_bucketed(
        self,
        *,
        vegas: list[float] | list[list[float]],
        expiry_buckets: list[float] | list[list[float]],
        strike_buckets: list[float] | list[list[float]],
        n_expiry: int,
        n_strike: int,
    ) -> dict[str, Any]:
        """Aggregate option vegas onto a bucketed (expiry × strike) surface.

        Each option's vega is summed into its (expiry, strike) bucket. Total vega is
        conserved — the surface sum equals the input vega sum.

        Returns:
            The raw API response as a dict.
        """
        body = {
            "vegas": vegas,
            "expiry_buckets": expiry_buckets,
            "strike_buckets": strike_buckets,
            "n_expiry": n_expiry,
            "n_strike": n_strike,
        }
        return self._client._request(
            "POST", "/api/v1/market-risk/vega_surface_bucketed", json_body=body
        )

    def volatility_surface_implied_vol(
        self,
        *,
        market_prices: list[float] | list[list[float]],
        strikes: list[float] | list[list[float]],
        expiries: list[float] | list[list[float]],
        spot: float,
        rate: float,
        option_type: str = "call",
    ) -> dict[str, Any]:
        """Back out the implied-volatility surface from market option prices.

        For each quoted option the Black-Scholes equation is inverted for implied
        volatility by bisection. Round-tripping (pricing at the recovered IV)
        reproduces the input price.

        Returns:
            The raw API response as a dict.
        """
        body = {
            "market_prices": market_prices,
            "strikes": strikes,
            "expiries": expiries,
            "spot": spot,
            "rate": rate,
            "option_type": option_type,
        }
        return self._client._request(
            "POST", "/api/v1/market-risk/volatility_surface_implied_vol", json_body=body
        )

    def volga_vega_convexity(
        self,
        *,
        spot: float,
        strike: float,
        rate: float,
        sigma: float,
        tau: float,
        div_yield: float = 0.0,
    ) -> dict[str, Any]:
        """Volga (vomma) — convexity of value in volatility (∂²V/∂σ² = ∂vega/∂σ).

        ``Volga = vega · d1 · d2 / σ``. Identical for calls and puts. Positive volga
        means the position is long volatility-of-volatility.

        Returns:
            The raw API response as a dict.
        """
        body = {
            "spot": spot,
            "strike": strike,
            "rate": rate,
            "sigma": sigma,
            "tau": tau,
            "div_yield": div_yield,
        }
        return self._client._request(
            "POST", "/api/v1/market-risk/volga_vega_convexity", json_body=body
        )
